-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'Fundamentos de UI / UX' and a.numero = 8
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 08 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 08', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 08 (20 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/FUNDAMENTOS-DE-UI-UX/ATIVIDADES/ATIVIDADE-PRATICA-AULA-08.html', 20, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Explique o papel do tamanho relativo na definição da ordem de leitura da tela.', 0.2, 'O tamanho relativo define o que o olho vê primeiro, depois e por último. Um elemento maior sugere automaticamente mais importância e ancora a leitura antes da análise detalhada. Quando todos os textos têm quase o mesmo tamanho, nenhum deles se destaca e o usuário não sabe por onde começar.', 'Nota cheia: explica que o tamanho relativo estabelece a ordem de leitura (primeiro, segundo, último) e que o maior elemento atrai o olhar antes da leitura. Metade: cita que o tamanho importa para a ordem de leitura, sem explicar a relação entre tamanho relativo e ordem. Zero: em branco, não relaciona tamanho com ordem de leitura ou copia o enunciado.'),
      (v_atividade, 1, 2, 'Cite os três níveis de leitura (títulos, subtítulos e corpo) e a função de cada um.', 0.4, 'Título é o gancho da página: conciso, legível à distância e que informa o assunto de imediato. Subtítulo agrupa tópicos e contextualiza quem está só escaneando a seção. Corpo traz detalhes, dados e explicações completas, em tamanho confortável para leitura contínua (16 a 18 px).', 'Nota cheia: cita os três níveis (títulos, subtítulos e corpo) e a função de cada um, com as palavras do aluno. Metade: cita os três níveis, mas explica a função de apenas um ou de forma incompleta. Zero: em branco, cita níveis que não são da aula ou não explica nenhuma função.'),
      (v_atividade, 1, 3, 'Proponha uma correção para a tela analisada, com base nesses níveis.', 0.4, 'Na tela analisada, o título deve ficar em destaque (por exemplo, 32 px em negrito), os subtítulos das seções em um degrau abaixo (cerca de 24 px) e o texto corrido em 16 px. Assim a tela ganha três níveis claros e a leitura começa pelo título.', 'Nota cheia: propõe valores ou degraus para título, subtítulo e corpo, com a hierarquia de três níveis e a correção do problema observado. Metade: propõe aumentar o título ou diferenciar os níveis, sem valores nem a relação entre os três níveis. Zero: em branco, não corrige o problema ou propõe mudança sem relação com a hierarquia.'),
      (v_atividade, 2, 1, 'Liste os degraus da escala tipográfica de interface e a faixa de tamanho de cada um.', 0.2, 'A escala de interface tem quatro degraus: legendas (12 a 14 px), corpo (16 a 18 px), subtítulo (20 a 24 px) e título H1 (32 a 40 px). As legendas servem a metadados e notas de rodapé; o corpo é o padrão de leitura contínua; o subtítulo separa seções e cartões; o H1 cria impacto na abertura.', 'Nota cheia: lista os quatro degraus com as faixas de tamanho corretas (12 a 14, 16 a 18, 20 a 24 e 32 a 40 px). Metade: lista os degraus com uma ou duas faixas erradas ou incompletas. Zero: em branco, lista degraus inventados ou sem faixa de tamanho.'),
      (v_atividade, 2, 2, 'Explique por que o corpo do texto deve ficar em uma faixa confortável para leitura contínua.', 0.4, 'O corpo do texto precisa de tamanho confortável (16 a 18 px) para que a leitura contínua seja cansativa o menos possível. Tamanho pequeno obriga o olho a esforçar-se em cada linha e o usuário desiste de ler textos longos.', 'Nota cheia: explica que a faixa de 16 a 18 px garante conforto na leitura contínua e que tamanhos menores cansam ou atrapalham a leitura. Metade: menciona conforto de leitura sem citar a faixa ou sem explicar o motivo. Zero: em branco ou afirma que o tamanho do corpo não importa.'),
      (v_atividade, 2, 3, 'Justifique a escolha de uma escala com poucos degraus, em vez de tamanhos variados em cada tela.', 0.4, 'Poucos degraus facilitam a consistência, porque cada tipo de texto tem um tamanho fixo e a equipe repete sempre o mesmo. Com tamanhos variados em cada tela, a interface parece desorganizada e o desenvolvedor precisa decidir valores novos a cada vez, o que aumenta a chance de erro.', 'Nota cheia: relaciona poucos degraus com repetição e consistência, e explica que tamanhos variados geram improviso ou desorganização. Metade: justifica pela facilidade de aplicação sem relacionar com consistência. Zero: em branco ou defende tamanhos variados por tela.'),
      (v_atividade, 3, 1, 'Explique por que os dedos exigem alvos de toque maiores do que um ponteiro de mouse.', 0.2, 'O dedo é muito menos preciso que a ponta de um ponteiro de mouse, que age com um único pixel. Por isso o alvo de toque precisa ser maior para que o usuário acerte o botão desejado sem tentar várias vezes.', 'Nota cheia: explica que o dedo tem menos precisão que o ponteiro do mouse e que isso exige alvos maiores. Metade: diz apenas que o dedo é maior ou menos preciso, sem ligar isso ao tamanho do alvo. Zero: em branco ou atribui o problema a outra causa.'),
      (v_atividade, 3, 2, 'Informe o tamanho mínimo recomendado para uma área de toque e a consequência de botões abaixo de 32 px.', 0.4, 'O tamanho mínimo recomendado para a área de toque é de 48 × 48 px, segundo as diretrizes da Apple e do Google citadas na aula. Botões com menos de 32 px causam cliques acidentais e frustração no usuário móvel.', 'Nota cheia: informa 48 × 48 px como mínimo e explica que botões abaixo de 32 px causam cliques acidentais e frustração. Metade: informa o tamanho mínimo correto, sem a consequência, ou o contrário. Zero: em branco ou informa valor diferente de 48 px sem justificativa da aula.'),
      (v_atividade, 3, 3, 'Indique como você ajustaria o botão de agendamento para atender a essa recomendação.', 0.4, 'Aumentar a altura do botão de agendamento para pelo menos 48 px, garantindo área de toque de 48 × 48 px, e manter a área clicável com folga em volta do texto, para que ele não fique pequeno demais.', 'Nota cheia: propõe altura mínima de 48 px (ou área de toque de 48 × 48 px) para o botão e explica o ajuste. Metade: propõe aumentar o botão sem valor mínimo ou com valor abaixo de 48 px. Zero: em branco ou propõe reduzir ou manter o botão.'),
      (v_atividade, 4, 1, 'Explique o que é espaço em branco (ou espaço negativo) em UI design.', 0.2, 'Espaço em branco, ou espaço negativo, é a área vazia entre elementos. Em UI design ele é um elemento ativo, tão importante quanto uma imagem ou um botão, porque permite respirar, separa blocos de ideias e guia o olhar sem bordas pesadas.', 'Nota cheia: define o espaço em branco como área vazia que é elemento ativo e que separa blocos ou guia o olhar. Metade: define como espaço vazio, sem o papel no design. Zero: em branco ou trata o espaço vazio como desperdício.'),
      (v_atividade, 4, 2, 'Relacione a falta de espaço ao cansaço visual e à sobrecarga cognitiva do usuário.', 0.4, 'Tela cheia de ícones, textos e bordas sem margens provoca fadiga visual. O cérebro gasta energia extra apenas para descobrir onde termina um campo e começa outro, o que gera sobrecarga cognitiva e cansaço ao preencher o formulário.', 'Nota cheia: relaciona a falta de espaço com fadiga visual e com sobrecarga cognitiva (gasto de energia para separar campos). Metade: relaciona a falta de espaço com cansaço, sem explicar a sobrecarga cognitiva. Zero: em branco ou nega a relação.'),
      (v_atividade, 4, 3, 'Descreva duas mudanças de espaçamento que você faria na tela, sem acrescentar bordas pesadas.', 0.4, 'Duas mudanças possíveis: aumentar as margens externas entre os blocos do formulário (por exemplo, 24 px de espaço vazio no lugar de uma borda grossa) e aumentar o respiro interno dos campos, separando rótulo e campo por espaço. Nenhuma das duas exige bordas pesadas.', 'Nota cheia: descreve duas mudanças de espaçamento concretas (margens entre blocos, respiro interno, separação de campos ou blocos) e que não usam bordas pesadas. Metade: descreve uma mudança concreta ou duas genéricas ("mais espaço"). Zero: em branco ou propõe bordas pesadas ou divisórias como solução.'),
      (v_atividade, 5, 1, 'Defina a lei da proximidade e o que ela faz o cérebro perceber.', 0.2, 'A lei da proximidade diz que elementos posicionados perto uns dos outros são percebidos pelo cérebro como parte de uma mesma categoria. O espaço, portanto, comunica quais itens se relacionam.', 'Nota cheia: define a lei da proximidade como agrupamento pelo espaço, em que elementos próximos são vistos como uma categoria. Metade: define de forma vaga, dizendo apenas que elementos próximos "ficam juntos", sem o sentido de categoria. Zero: em branco ou define outra lei.'),
      (v_atividade, 5, 2, 'Explique por que o rótulo deve ficar mais próximo do seu próprio campo.', 0.4, 'Se o rótulo estiver mais perto do campo anterior, o cérebro o associa ao bloco de cima. O rótulo deve estar mais próximo do seu próprio input do que do bloco anterior, para que o usuário saiba a qual campo ele pertence e não erre o preenchimento.', 'Nota cheia: explica que o rótulo mais próximo do próprio campo deixa a associação clara e evita erro de preenchimento. Metade: diz que o rótulo deve ficar perto do campo, sem explicar a associação com o erro. Zero: em branco ou defende o contrário.'),
      (v_atividade, 5, 3, 'Diga como separar as seções do formulário sem usar linhas divisórias cinzas.', 0.4, 'Separar as seções com margens externas maiores, por exemplo 32 px entre seções, em vez de linhas divisórias cinzas ou bordas carregadas. O espaço vazio cria o agrupamento sem poluir a tela.', 'Nota cheia: propõe separar seções por margem externa maior (espaço vazio) e não por linhas ou bordas. Metade: propõe espaço entre seções sem indicar que a margem deve ser maior, ou usa uma linha fina. Zero: em branco ou propõe linhas divisórias cinzas ou bordas pesadas.'),
      (v_atividade, 6, 1, 'Explique o que significa a base de 8 px no sistema de espaçamento.', 0.2, 'A base de 8 px significa que todos os espaçamentos da interface são múltiplos de 8: 8, 16, 24, 32, 40 ou 48 px. O designer deixa de escolher números aleatórios e segue uma sequência única.', 'Nota cheia: explica que todos os espaçamentos são múltiplos de 8 px e cita alguns valores. Metade: diz que a base é 8 px, sem explicar que os espaçamentos são múltiplos. Zero: em branco ou explica de outra forma sem relação com múltiplos de 8.'),
      (v_atividade, 6, 2, 'Indique por que a grade de 8 pontos facilita o trabalho de quem programa o CSS.', 0.4, 'A grade de 8 pontos facilita o código CSS porque os valores ficam padronizados e podem virar variáveis reutilizáveis. Os componentes se alinham em qualquer resolução e o time de front-end não precisa interpretar números soltos como 11 px ou 17 px.', 'Nota cheia: relaciona a grade com valores padronizados ou variáveis CSS e com a facilidade de manutenção. Metade: diz apenas que facilita o código, sem explicar o motivo. Zero: em branco ou afirma que a grade complica o código.'),
      (v_atividade, 6, 3, 'Cite os valores de espaçamento que você usaria para micro, padrão, médio e macro espaços.', 0.4, 'Micro: 8 px (espaço interno, por exemplo entre ícone e texto dentro do botão). Padrão: 16 px (gaps e margens). Médio: 24 px (entre cartões). Macro: 32 px (entre seções).', 'Nota cheia: cita os quatro valores (8, 16, 24 e 32 px) associados corretamente a micro, padrão, médio e macro. Metade: cita os valores, mas associa um ou dois deles ao nível errado, ou cita apenas três. Zero: em branco ou cita valores fora da escala de 8 pontos.'),
      (v_atividade, 7, 1, 'Indique o valor de espaçamento que você adotaria entre seções e por quê.', 0.2, 'O valor adotado entre seções é 32 px (macro), porque ele cria separação nítida entre o cabeçalho e o conteúdo central e é múltiplo de 8.', 'Nota cheia: indica 32 px (ou outro múltiplo de 8 maior que os usados entre cartões) e justifica pela separação nítida entre seções. Metade: indica um múltiplo de 8 sem justificativa, ou valor que não é múltiplo de 8 com justificativa. Zero: em branco ou indica 20 px ou 30 px.'),
      (v_atividade, 7, 2, 'Explique por que valores como 20 px e 30 px não fazem parte da escala de 8 pontos.', 0.4, 'A escala de 8 pontos usa múltiplos de 8 (8, 16, 24, 32, 40, 48). Os valores 20 px e 30 px não são múltiplos de 8, então ficam fora da escala e geram distâncias irregulares, sem ritmo visual.', 'Nota cheia: explica que 20 e 30 não são múltiplos de 8 e que por isso fogem da escala e quebram o ritmo. Metade: diz que não estão na escala, sem verificar a divisão por 8. Zero: em branco ou afirma que são múltiplos de 8.'),
      (v_atividade, 7, 3, 'Descreva como a separação entre seções ajuda o usuário a entender a estrutura da página.', 0.4, 'A separação entre seções mostra ao usuário onde começa e termina cada parte da página. Com um espaço macro claro entre o cabeçalho e o conteúdo, o olho entende a estrutura sem precisar ler tudo.', 'Nota cheia: relaciona a separação entre seções com a compreensão da estrutura da página e com o agrupamento visual. Metade: diz que a separação ajuda, sem explicar como a estrutura é percebida. Zero: em branco ou afirma que a separação não importa.'),
      (v_atividade, 8, 1, 'Explique por que texturas pesadas e imitações de materiais não são recomendadas nas interfaces modernas.', 0.2, 'Texturas pesadas, imitações de madeira e plástico (skeuomorfismo) não são recomendadas porque as interfaces modernas constroem profundidade com recursos sutis. Elas pesam visualmente, competem pela atenção do usuário e não ajudam a entender a interface.', 'Nota cheia: explica que as interfaces modernas não usam texturas pesadas nem imitações de materiais e que isso compete com o conteúdo ou atrapalha a leitura. Metade: diz que não são modernas, sem motivo. Zero: em branco ou defende texturas e imitações.'),
      (v_atividade, 8, 2, 'Descreva como a profundidade é construída hoje, com elevação, sobreposição e sombras.', 0.4, 'A profundidade é construída com elevação (o elemento sobe em relação ao fundo), sobreposição (um elemento fica sobre outro) e sombras difusas e sutis. Essas três pistas mostram o que está acima e o que está abaixo sem usar texturas.', 'Nota cheia: cita elevação, sobreposição e sombras difusas, explicando como cada uma cria profundidade. Metade: cita duas das três, ou as três sem explicação. Zero: em branco ou cita texturas, brilhos ou bordas pesadas como forma de profundidade.'),
      (v_atividade, 8, 3, 'Indique os valores sugeridos para uma sombra suave e a finalidade da camada superior.', 0.4, 'Uma sombra suave tem blur alto e opacidade baixa, entre 10% e 15%. A camada superior indica o elemento em foco ou a ação interativa (como um cartão clicável ou um menu modal), criando a ordem de camadas.', 'Nota cheia: indica blur alto com opacidade entre 10% e 15% e explica que a camada superior mostra o elemento em foco ou ação interativa. Metade: indica a sombra suave sem valores, ou a camada sem a finalidade. Zero: em branco ou propõe sombras fortes ou escuras.'),
      (v_atividade, 9, 1, 'Explique o papel de cada camada: fundo base, superfície do cartão e janela modal.', 0.2, 'O fundo base é a camada mais profunda, neutra e fosca, que dá estabilidade e contraste. A superfície do cartão fica levemente mais clara que o fundo para destacar agrupamentos sem bordas pretas. A janela modal fica na camada mais alta, com elevação máxima.', 'Nota cheia: explica o papel das três camadas (fundo base estável, cartão levemente mais claro e modal em elevação máxima). Metade: explica duas camadas ou o papel de forma genérica. Zero: em branco ou inverte a ordem de camadas.'),
      (v_atividade, 9, 2, 'Explique como o estado de foco (hover) comunica que um item está ativo.', 0.4, 'Quando o mouse passa sobre o item (hover) ou o botão é pressionado, a sombra aumenta. Essa mudança comunica que o item está ativo ou pode ser clicado, sem precisar de texto.', 'Nota cheia: explica que o aumento da sombra no hover ou no clique sinaliza que o item está ativo. Metade: diz que o hover muda o visual, sem explicar a sinalização de ativo. Zero: em branco ou não relaciona o hover com a ativação.'),
      (v_atividade, 9, 3, 'Justifique por que a janela modal deve ter elevação máxima e um fundo escurecido.', 0.4, 'A janela modal pede uma decisão crítica. A elevação máxima a coloca acima de tudo, e o scrim escurecido ao fundo retém a atenção do usuário, para que ele decida antes de voltar ao restante da tela.', 'Nota cheia: justifica a elevação máxima pela prioridade da decisão e o fundo escurecido pela retenção da atenção. Metade: justifica apenas um dos dois elementos. Zero: em branco ou propõe modal sem destaque nem fundo escurecido.'),
      (v_atividade, 10, 1, 'Defina o princípio da repetição no design de interfaces.', 0.2, 'O princípio da repetição afirma que características visuais (fontes, cores, raios de arredondamento, formatos de caixas e estilos de ícones) devem ser reutilizadas de forma sistemática em toda a interface, para criar unidade.', 'Nota cheia: define a repetição como reutilização sistemática de características visuais por toda a interface. Metade: define como "usar a mesma coisa" sem o caráter sistemático. Zero: em branco ou define de outra forma.'),
      (v_atividade, 10, 2, 'Explique como a diferença entre os botões afeta a consistência e a confiança do usuário.', 0.4, 'Botões com formas e cores diferentes entre as telas quebram a consistência. O usuário aprende um padrão numa tela e não o reconhece na outra, o que faz duvidar se são sistemas diferentes e reduz a confiança no sistema.', 'Nota cheia: explica que a diferença quebra a consistência, que o usuário não reconhece o padrão e que isso reduz a confiança. Metade: diz que a diferença confunde, sem ligar à confiança. Zero: em branco ou afirma que a diferença não importa.'),
      (v_atividade, 10, 3, 'Diga quais elementos devem ser repetidos em todas as telas do sistema.', 0.4, 'Devem ser repetidos em todas as telas: a cor, a altura e o arredondamento dos botões primários; as fontes; o estilo dos ícones (sem misturar preenchimento sólido com linha fina); e a estrutura dos cartões (mesma moldura e proporção para itens de mesmo valor hierárquico).', 'Nota cheia: cita pelo menos três elementos repetidos (botões com cor, altura e arredondamento; fontes; estilo de ícones; estrutura de cartões), ligados à aula. Metade: cita um ou dois elementos. Zero: em branco ou cita elementos que não são da aula sem relação com repetição.'),
      (v_atividade, 11, 1, 'Defina consistência interna e consistência externa.', 0.2, 'Consistência interna são as mesmas regras mantidas dentro da mesma tela e entre as telas do mesmo aplicativo. Consistência externa é o alinhamento com as convenções conhecidas da internet, como o carrinho no topo direito.', 'Nota cheia: define os dois níveis, com interna (dentro do aplicativo) e externa (convenções conhecidas da internet). Metade: define um nível corretamente e o outro de forma vaga. Zero: em branco ou inverte os conceitos.'),
      (v_atividade, 11, 2, 'Diga em qual nível de consistência se enquadra o problema do ícone e explique o motivo.', 0.4, 'O problema está na consistência externa, porque o carrinho no canto inferior esquerdo foge da convenção que os usuários já conhecem (o carrinho costuma ficar no topo direito). As regras internas do app estão coerentes, então o problema não é interno.', 'Nota cheia: classifica o problema como consistência externa e justifica pela quebra da convenção conhecida. Metade: indica externa sem justificativa clara, ou cita interna com explicação parcial. Zero: em branco ou classifica sem justificativa ou de forma errada.'),
      (v_atividade, 11, 3, 'Proponha uma solução que respeite as convenções conhecidas da internet.', 0.4, 'Colocar o ícone de carrinho no topo direito, como os usuários já esperam em lojas on-line, para que ele seja encontrado sem esforço e siga a convenção externa.', 'Nota cheia: propõe mover o carrinho para o topo direito (ou outra convenção conhecida) e explica que isso respeita o padrão dos usuários. Metade: propõe mudar o ícone de lugar sem indicar a convenção. Zero: em branco ou propõe manter o ícone onde está ou criar convenção nova.'),
      (v_atividade, 12, 1, 'Explique o que é a falta de regras de margem e o efeito que ela causa.', 0.2, 'A falta de regras de margem faz textos e botões encostarem nas bordas da tela ou do cartão. O conteúdo fica apertado, sem respiro, o que dificulta a leitura e aumenta o cansaço visual.', 'Nota cheia: explica que faltam margens e que o conteúdo encosta nas bordas, com efeito de aperto, leitura difícil ou cansaço. Metade: diz que faltam margens, sem efeito. Zero: em branco ou confunde com outro problema.'),
      (v_atividade, 12, 2, 'Explique por que o excesso de divisórias polui a tela e como o espaço vazio pode substituí-las.', 0.4, 'Excesso de divisórias (bordas pretas grossas) polui a tela e cansa o olho. O espaço vazio pode substituir essas linhas, porque 24 px de espaço já separam os blocos sem carregar a tela.', 'Nota cheia: explica que as divisórias poluem e que o espaço vazio separa os blocos no lugar delas. Metade: diz que as divisórias poluem, sem propor o espaço vazio. Zero: em branco ou defende bordas grossas.'),
      (v_atividade, 12, 3, 'Indique uma regra simples de margem que você aplicaria em toda a interface.', 0.4, 'Uma regra simples de margem: usar múltiplos de 8 px, por exemplo 16 px de margem interna em cartões e 24 px ou 32 px entre blocos, aplicados igualmente em toda a interface.', 'Nota cheia: propõe uma regra de margem concreta (valor em múltiplo de 8 px, aplicado a toda a interface). Metade: propõe uma margem sem valor, ou com valor sem a regra de aplicação geral. Zero: em branco ou propõe margens diferentes para cada tela.'),
      (v_atividade, 13, 1, 'Explique o que é a chamada "salada de fontes" e por que ela polui visualmente a tela.', 0.2, '"Salada de fontes" é a mistura de muitas famílias tipográficas sem propósito estrutural. A tela fica poluída porque cada fonte compete pela atenção e nenhuma das escolhas tem um papel claro.', 'Nota cheia: explica que é a mistura de várias famílias sem propósito e que isso polui a tela e confunde o olhar. Metade: define a mistura, sem explicar a poluição. Zero: em branco ou define de outra forma.'),
      (v_atividade, 13, 2, 'Explique o papel da tipografia na legibilidade e no tom visual da interface.', 0.4, 'A tipografia define a legibilidade e o tom visual da interface. Uma fonte bem escolhida e bem aplicada facilita a leitura e transmite a mesma identidade em todo o sistema.', 'Nota cheia: relaciona tipografia com legibilidade e com o tom visual da interface. Metade: relaciona com apenas um dos dois. Zero: em branco ou afirma que a tipografia não importa.'),
      (v_atividade, 13, 3, 'Proponha quantas famílias tipográficas usar e como distribuí-las na página.', 0.4, 'Usar no máximo duas famílias tipográficas: uma para os títulos e outra para o corpo, os botões e os textos de apoio, diferenciando os níveis pelo tamanho e pelo peso (negrito) da escala, e não pela troca de fonte.', 'Nota cheia: propõe poucas famílias (uma ou duas) e explica a distribuição por função (títulos, corpo, botões), diferenciando os níveis por tamanho e peso. Metade: propõe poucas famílias sem explicar a distribuição. Zero: em branco ou mantém várias famílias sem critério.'),
      (v_atividade, 14, 1, 'Explique por que alturas diferentes para o mesmo botão prejudicam a repetição.', 0.2, 'Alturas diferentes para o mesmo botão quebram a repetição. O usuário não reconhece que as duas telas trazem a mesma ação e perde a previsibilidade do sistema.', 'Nota cheia: explica que alturas diferentes rompem a repetição e impedem o reconhecimento da mesma ação. Metade: diz que o botão fica diferente, sem relacionar à repetição ou à ação. Zero: em branco ou afirma que a diferença não importa.'),
      (v_atividade, 14, 2, 'Diga qual deve ser a altura mínima do botão primário e por que ela importa.', 0.4, 'A altura mínima do botão primário é de 48 px. Ela importa porque garante a área de toque confortável para os dedos e mantém o mesmo padrão em todas as telas.', 'Nota cheia: informa 48 px e relaciona com o toque confortável ou com a repetição. Metade: informa 48 px sem justificativa, ou justificativa sem o valor. Zero: em branco ou informa valor diferente sem justificativa da aula.'),
      (v_atividade, 14, 3, 'Descreva como registrar essa regra no guia visual do projeto.', 0.4, 'A regra deve ser registrada no guia visual do projeto como uma especificação fixa, por exemplo "Botão primário: altura 48 px", com a cor, o raio e o padding, para que designers e programadores sigam o mesmo valor.', 'Nota cheia: descreve o registro da regra no guia visual como valor fixo e de uso obrigatório, com a altura de 48 px. Metade: diz que deve ser registrada no guia, sem o valor ou o caráter obrigatório. Zero: em branco ou propõe deixar a regra só na memória da equipe.'),
      (v_atividade, 15, 1, 'Defina o guia visual e o papel que ele cumpre na equipe.', 0.2, 'O guia visual (style guide) é o documento oficial que registra todas as decisões visuais do projeto, como o "livro de regras" da interface. Ele serve de referência para toda a equipe.', 'Nota cheia: define o guia como documento oficial de decisões visuais e explica seu papel de referência comum da equipe. Metade: define o guia sem o papel na equipe. Zero: em branco ou define como outra coisa.'),
      (v_atividade, 15, 2, 'Liste três decisões que o guia deve fixar para a página de agendamento.', 0.4, 'Três decisões: escala de fontes (H1 32 px em negrito, H2 24 px, corpo 16 px); grade de espaços em múltiplos de 8 px (8 px interno, 16 px entre itens, 32 px entre seções); e especificações do botão primário (altura 48 px, raio 8 px, padding 16 px) e do cartão (raio 12 px).', 'Nota cheia: lista três decisões corretas e específicas para a página, com valores da aula. Metade: lista três decisões, mas uma ou mais sem valor ou genéricas ("usar uma fonte"). Zero: em branco ou lista decisões que não são visuais da página.'),
      (v_atividade, 15, 3, 'Explique como o guia evita que cada designer ou programador decida um padrão diferente.', 0.4, 'O guia fixa os valores, então cada designer ou programador consulta a mesma regra em vez de decidir um padrão próprio. Com a fonte, a cor e a margem definidas em um lugar só, o resultado fica consistente mesmo com pessoas diferentes trabalhando.', 'Nota cheia: explica que o guia fixa valores únicos que todos consultam, evitando padrões individuais e garantindo consistência. Metade: diz que o guia organiza a equipe, sem ligar a padrões individuais. Zero: em branco ou afirma que cada um deve decidir o padrão.'),
      (v_atividade, 16, 1, 'Informe a altura total do botão e explique por que ela é adequada ao toque dos dedos.', 0.2, 'A altura total de 48 px é adequada ao toque dos dedos porque atende ao tamanho mínimo ergonômico de toque (48 × 48 px). Um botão menor seria difícil de acertar e geraria cliques errados.', 'Nota cheia: informa 48 px e explica que atende ao mínimo de toque dos dedos, evitando erros. Metade: informa 48 px sem explicar a adequação ao toque. Zero: em branco ou informa outro valor sem relação com o toque.'),
      (v_atividade, 16, 2, 'Explique a função do arredondamento e do espaço interno nas laterais do botão.', 0.4, 'O arredondamento de 8 px deixa o botão com canto sutil, que confere modernidade sem parecer infantil. O espaço interno de 16 px nas laterais impede que o texto fique comprimido e encostado nas pontas do botão.', 'Nota cheia: explica que o raio de 8 px dá canto sutil e moderno, e que o padding de 16 px nas laterais evita o texto comprimido. Metade: explica apenas um dos dois elementos. Zero: em branco ou atribui outra função a eles.'),
      (v_atividade, 16, 3, 'Diga o que aconteceria com o texto do botão se o espaço interno fosse removido.', 0.4, 'Sem o espaço interno, o texto ficaria comprimido e encostado nas bordas do botão, com aparência apertada e difícil de ler, e o botão perderia clareza para o usuário.', 'Nota cheia: descreve o texto encostado ou comprimido nas pontas, com perda de legibilidade ou aparência apertada. Metade: diz que o texto ficaria apertado, sem o efeito de legibilidade. Zero: em branco ou afirma que nada mudaria.'),
      (v_atividade, 17, 1, 'Explique por que itens de mesmo valor hierárquico devem usar a mesma moldura e proporção.', 0.2, 'Itens com o mesmo valor hierárquico devem usar a mesma moldura e a mesma proporção porque o usuário os reconhece como do mesmo tipo. Se um cartão for diferente do outro, a leitura muda sem razão aparente.', 'Nota cheia: explica que a mesma moldura e proporção sinalizam o mesmo tipo de item e evitam confusão. Metade: diz que devem ser iguais, sem o motivo. Zero: em branco ou propõe molduras diferentes para itens iguais.'),
      (v_atividade, 17, 2, 'Indique um raio de arredondamento adequado para os cartões e compare com o do botão.', 0.4, 'Um raio de arredondamento adequado para os cartões é 12 px. Em comparação, o botão usa 8 px, por isso o cartão tem canto um pouco mais arredondado que o botão, e ambos seguem a mesma regra de repetição.', 'Nota cheia: indica 12 px para o cartão e compara com o botão (8 px), explicando a diferença. Metade: indica um raio sem comparação, ou compara sem o valor. Zero: em branco ou indica valor que não está na aula sem justificativa.'),
      (v_atividade, 17, 3, 'Descreva como o usuário se beneficia quando aprende o comportamento de um cartão.', 0.4, 'Quando o usuário aprende como um cartão se comporta (por exemplo, que o cartão clicável responde ao hover com sombra), ele aplica esse aprendizado a todos os cartões e não precisa reaprender a cada tela. Isso gera segurança e rapidez.', 'Nota cheia: explica que o aprendizado de um cartão vale para os outros e poupa esforço, com segurança ou rapidez no uso. Metade: diz que o usuário se beneficia, sem explicar o aprendizado. Zero: em branco ou afirma que cada cartão deve ser diferente.'),
      (v_atividade, 18, 1, 'Relacione cada valor da proposta (32 px, 24 px e 16 px) ao seu nível de leitura.', 0.2, '32 px corresponde ao nível 1, títulos (H1), que é o gancho da página. 24 px corresponde ao nível 2, subtítulos, que agrupam tópicos e contextualizam a seção. 16 px corresponde ao nível 3, corpo, que traz os detalhes e deve ficar em tamanho confortável para leitura contínua.', 'Nota cheia: relaciona os três valores aos três níveis corretos (título, subtítulo e corpo) e explica cada função. Metade: relaciona dois dos três valores corretamente. Zero: em branco ou relaciona os valores aos níveis errados.'),
      (v_atividade, 18, 2, 'Explique por que a escala não deve pular etapas entre os níveis.', 0.4, 'A escala não deve pular etapas porque cada nível precisa ser claramente diferente do anterior e do seguinte. Saltos grandes ou repetidos deixam os níveis confusos, e o usuário perde a noção de ordem de importância.', 'Nota cheia: explica que cada degrau deve ser distinto e que pular etapas confunde a hierarquia e a ordem de importância. Metade: diz que a escala deve ser contínua, sem explicar o efeito na hierarquia. Zero: em branco ou defende pular etapas.'),
      (v_atividade, 18, 3, 'Indique um ajuste para as legendas e os metadados da página, com base na escala.', 0.4, 'Legendas e metadados devem usar o degrau de legenda da escala, entre 12 e 14 px, para ficarem abaixo do corpo e não competirem com o texto principal.', 'Nota cheia: indica o degrau de legenda (12 a 14 px) para legendas e metadados e explica que ficam abaixo do corpo. Metade: indica o degrau sem a explicação, ou um valor fora da faixa com a explicação. Zero: em branco ou propõe usar o título para legendas.'),
      (v_atividade, 19, 1, 'Verifique se as medidas de espaçamento são múltiplos de 8 px e explique o resultado.', 0.2, 'Os valores de 10 px, 15 px e 20 px não são múltiplos de 8 px. Portanto o guia não cumpre a regra de 8 pontos. Os valores corretos seriam 8, 16, 24 ou 32 px.', 'Nota cheia: verifica os três valores, conclui que nenhum (ou apenas algum específico) é múltiplo de 8 e sugere múltiplos de 8. Metade: conclui que o guia não cumpre a regra, sem verificar cada valor. Zero: em branco ou afirma que os valores estão corretos.'),
      (v_atividade, 19, 2, 'Verifique se o botão primário atende ao tamanho mínimo para toque e explique o resultado.', 0.4, 'O botão primário de 36 px não atende ao tamanho mínimo de toque, que é 48 × 48 px. O guia deve ser corrigido para 48 px de altura.', 'Nota cheia: conclui que 36 px não atende ao mínimo de 48 px e explica a relação com o toque dos dedos. Metade: conclui que não atende, sem o valor de referência. Zero: em branco ou afirma que atende.'),
      (v_atividade, 19, 3, 'Escreva uma sugestão de melhoria para o guia, fundamentada em um critério técnico.', 0.4, 'Sugestão: adotar a grade de 8 pontos para todos os espaçamentos (8, 16, 24 e 32 px) e fixar a altura do botão primário em 48 px, justificando pela regra técnica da aula (grade de 8 pontos e alvo de toque mínimo).', 'Nota cheia: sugere uma melhoria concreta, fundamentada em critério técnico da aula (múltiplos de 8 px ou alvo mínimo de 48 px). Metade: sugere melhoria sem critério técnico, ou com critério sem valor. Zero: em branco ou sugere manter os valores.'),
      (v_atividade, 20, 1, 'Explique o que o tamanho define na ordem em que o olhar escaneia a interface.', 0.2, 'O tamanho define a ordem em que o olhar escaneia a interface. O elemento maior ancora a leitura e mostra o que é mais importante, antes da leitura analítica.', 'Nota cheia: explica que o tamanho determina a ordem de escaneamento e o que é visto primeiro. Metade: diz que o tamanho guia o olhar, sem explicar a ordem. Zero: em branco ou atribui essa função a outro elemento.'),
      (v_atividade, 20, 2, 'Explique como o espaço agrupa conteúdos correlatos e reduz o cansaço visual.', 0.4, 'O espaço agrupa conteúdos correlatos, pela lei da proximidade, e separa blocos diferentes. Com espaço vazio suficiente, a tela deixa de ser um amontoado e o usuário sente menos cansaço visual.', 'Nota cheia: explica o agrupamento de conteúdos correlatos (proximidade) e a redução do cansaço visual. Metade: cita apenas um dos dois efeitos. Zero: em branco ou afirma que o espaço não agrupa nem reduz cansaço.'),
      (v_atividade, 20, 3, 'Explique como a repetição gera consistência, previsibilidade e confiança, e recomende uma ação para a equipe.', 0.4, 'A repetição gera consistência e previsibilidade: o usuário aprende o padrão uma vez e o reconhece em todas as telas, o que gera confiança. Recomendação para a equipe: criar e seguir um guia visual com escala tipográfica de 32, 24 e 16 px, espaçamentos em múltiplos de 8 px e botão primário de 48 px.', 'Nota cheia: explica como a repetição gera consistência, previsibilidade e confiança, e recomenda uma ação concreta para a equipe (guia visual ou regra definida, com valores da aula). Metade: explica a repetição, mas a recomendação é genérica ou sem valores. Zero: em branco ou não explica a repetição nem recomenda ação.');
end $$;
